function ActorPreview({ actorId, catalog, basePath }) { const route = assetRoute(catalog, "actor", actorId); return route ? <img src={routeUrl(basePath, route)} alt={actorId} /> : null; }

function AssetField({ label, kind, value, onChange, catalog, disabled }) { const debounced = useDebounced(value, 300); return <label className="field wide"><span>{label}</span><input value={value || ""} disabled={disabled} list={`story-${kind}-options`} onChange={(event) => onChange(event.target.value)} /><AssetPreview kind={kind} id={debounced} catalog={catalog} /></label>; }
