function TextField({ label, value, onChange, textarea, disabled }) { return <label className="field wide"><span>{label}</span>{textarea ? <textarea rows="3" value={value || ""} disabled={disabled} onChange={(event) => onChange(event.target.value)} /> : <input value={value || ""} disabled={disabled} onChange={(event) => onChange(event.target.value)} />}</label>; }
function NumberField({ label, value, onChange, min, max, step = 1, disabled }) { return <label className="field"><span>{label}</span><input type="number" value={value ?? ""} min={min} max={max} step={step} disabled={disabled} onChange={(event) => onChange(Number(event.target.value))} /></label>; }
function SelectField({ label, value, options, onChange, disabled }) { return <label className="field"><span>{label}</span><select value={value || options[0]} disabled={disabled} onChange={(event) => onChange(event.target.value)}>{options.map((item) => <option key={item}>{item}</option>)}</select></label>; }
function CheckField({ label, checked, onChange, disabled }) { return <label className="check-field wide"><input type="checkbox" checked={Boolean(checked)} disabled={disabled} onChange={(event) => onChange(event.target.checked)} /><span>{label}</span></label>; }
function ReadField({ label, value }) { return <label className="field read-field"><span>{label}</span><output>{String(value ?? "")}</output></label>; }

function Rewards({ label, value, onChange }) { return <details className="settings-group"><summary>{label}</summary><div className="reward-grid">{(value || []).map((reward, index) => <section key={index}><strong>Tier {index + 1}</strong><NumberField label="Completion rate" value={reward.completeRate} min={0} max={100} onChange={(next) => onChange(value.map((item, itemIndex) => itemIndex === index ? { ...item, completeRate: next } : item))} /><TextField label="Reward type" value={reward.rewardType} onChange={(next) => onChange(value.map((item, itemIndex) => itemIndex === index ? { ...item, rewardType: next } : item))} /><NumberField label="Reward ID" value={reward.rewardId} min={0} onChange={(next) => onChange(value.map((item, itemIndex) => itemIndex === index ? { ...item, rewardId: next } : item))} /><NumberField label="Reward value" value={reward.rewardValue} min={0} onChange={(next) => onChange(value.map((item, itemIndex) => itemIndex === index ? { ...item, rewardValue: next } : item))} /></section>)}</div></details>; }
function ResourceChange({ label, value, onChange }) { return <details className="settings-group"><summary>{label}</summary><div className="inspector-form"><TextField label="Mission condition" value={value?.missionCondition || ""} onChange={(next) => onChange({ ...value, missionCondition: next })} /><NumberField label="Mission value" value={value?.missionValue || 0} min={0} onChange={(next) => onChange({ ...value, missionValue: next })} /><TextField label="Background music" value={value?.backgroundMusic || ""} onChange={(next) => onChange({ ...value, backgroundMusic: next })} /></div></details>; }

