function fromSuggestion(value, title, scenes, definition) { return { title, stageDescription: value.stageDescription || title, difficulty: value.difficulty || "NORMAL", actId: value.actId, stageIndex: value.stageIndex, stageUiNumber: value.stageUiNumber, unlockDungeonId: value.unlockDungeonId, stageId: value.stageId, dungeonId: value.dungeonId, cutsceneId: value.cutsceneId, stageStrId: value.stageStrId, dungeonStrId: value.dungeonStrId, cutsceneStrId: value.cutsceneStrId, background: value.background || "CAFE", music: "", stageCharacter: value.stageCharacter || "NKM_UNIT_C_POLICE_LEE_YUMI", actBackground: value.actBackground || definition?.actBackground || "", episodeThumbnail: value.episodeThumbnail || definition?.thumbnail || "", dungeonIcon: value.dungeonIcon || "NKM_NPC_CUT_SCENE", scenes }; }
function fromAuthoring(stage) { const ui = stage.clientUi || {}, base = stage.base || {}, readOnly = stage.cutsceneReadOnly === true; return { operation: stage.operation, baseObjectId: base.objectId, baseSnapshot: base.snapshot, sourceObjectId: stage.operation === "clone" ? base.objectId : undefined, sourceStageId: base.stageId, sourceEpisodeId: base.episodeId, sourceCategory: base.category, sourceDifficulty: base.difficulty, cutsceneReadOnly: readOnly, forkCutscenes: stage.forkCutscenes === true, unlockRequirementType: stage.unlockRequirementType, title: stage.title, stageDescription: stage.stageDescription || ui.description || stage.title, difficulty: stage.placement.difficulty || "NORMAL", actId: stage.placement.actId, stageIndex: stage.placement.stageIndex, stageUiNumber: stage.placement.stageUiNumber, unlockDungeonId: stage.unlockDungeonId || 0, stageId: stage.ids.stageId, dungeonId: stage.ids.dungeonId, cutsceneId: stage.ids.cutsceneId || 0, stageStrId: stage.ids.stageStrId, dungeonStrId: stage.ids.dungeonStrId, cutsceneStrId: stage.ids.cutsceneStrId || "", background: stage.background || "CAFE", music: stage.music || "", stageCharacter: stage.stageCharacter || ui.avatar || "NKM_UNIT_C_POLICE_LEE_YUMI", actBackground: ui.actBackground || "", episodeThumbnail: ui.episodeThumbnail || "", dungeonIcon: ui.dungeonIcon || "", scenes: readOnly ? [] : stage.scenes || [blankScene()], previewScenes: readOnly ? stage.previewScenes || [] : undefined }; }
function setPath(root, path, value) { const next = structuredClone(root); let target = next; for (let index = 0; index < path.length - 1; index += 1) target = target[path[index]]; target[path.at(-1)] = value; return next; }
